import pyspark.sql.functions as F
from silver_core.journey_core import spark


# Configured dataset names

# ==== Configured dataset names ====
PUBLIC_SCHEMA = spark.conf.get("journey.public_schema")


INTERNAL_SCHEMA = spark.conf.get("journey.internal_schema")


def _n(name):
    """Flatten a logical journey plane name into the configured public/internal schema."""
    logical_schema, table = name.split(".", 1)
    if not logical_schema.startswith("journey_"):
        raise ValueError(f"unexpected flow schema in {name!r}")
    plane = logical_schema[len("journey_"):]
    if table.startswith("_"):
        return INTERNAL_SCHEMA + "._" + plane + table
    return PUBLIC_SCHEMA + "." + plane + "_" + table


# Reviewed form configuration helpers

# ==== Reviewed form configuration helpers ====
def _element_matches(element):
    # Use explicit configured matches, or expand the element's label and aliases into matching
    # rules.
    if element.get("matches"):
        return element["matches"]
    labels = [element["label"]] + element.get("aliases", [])
    return [{"label": label, "section": element.get("section")} for label in labels]


def _validate_config(cfg):
    # Reject duplicate output columns and unsupported response kinds before registering a form
    # instrument.
    columns = [element["column"] for element in cfg["elements"]]
    assert len(columns) == len(set(columns)), f"{cfg['slug']}: duplicate output columns"
    assert all(element["kind"] in {"NUMERIC", "CODED", "TEXT", "DATE"} for element in cfg["elements"])
    assert all(element["cardinality"] in {"single", "multi"} for element in cfg["elements"])

    keys = []
    for element in cfg["elements"]:
        for match in _element_matches(element):
            key = (
                match["label"].strip().upper(),
                (match.get("section") or "").strip().upper() or None,
            )
            keys.append(key)
    assert len(keys) == len(set(keys)), f"{cfg['slug']}: duplicate label/section match keys"


