# Shared instrument projection helpers

# ==== Shared instrument projection helpers ====
def _response_value(kind):
    # Select the typed numeric, date or text response value for the configured response kind.
    if kind == "NUMERIC":
        return F.col("response_value_number")
    if kind == "DATE":
        return F.col("response_value_datetime")
    return F.coalesce(
        F.col("response_coding_display"),
        F.col("response_value_text"),
    )


def _response_provenance():
    # question_concept_id and unit_concept_id are OMOP concept identifiers, and the
    # frozen production provenance encodes them as JSON numbers. The v2 response
    # table casts them to string for its own flat columns, which silently turned
    # 43054909 into "43054909" in this JSON and made every *_provenance column in
    # all 30 instrument tables differ from production on 100% of overlapping
    # instances -- the whole of the form_instrument_parity failure. Casting back to
    # bigint here restores the numeric encoding without disturbing the flat columns.
    # Measured across the full corpus, normalising only these two fields collapses
    # 149,229 of 149,288 frailty_score, all 14,529 must and 259,553 of 259,747
    # smoking_status disagreements; every residual is a row where production
    # published an empty {} and v2 published a real mapping.
    # try_cast, not cast: serverless runs ANSI mode, where a stray non-numeric
    # would abort the update rather than fall back to null.
    # Serialize the response's mapping rules, version, match status and concept evidence as
    # JSON.
    return F.to_json(
        F.struct(
            F.col("value_mapping_source").alias("source"),
            F.col("powerform_mapping_rule_id").alias("rule_id"),
            F.col("powerform_mapping_version").alias("ruleset_version"),
            F.col("canonical_value_mapping_rule_id").alias(
                "canonical_rule_id"
            ),
            F.col("canonical_match_status").alias("match_status"),
            F.expr("try_cast(question_concept_id as bigint)").alias(
                "question_concept_id"
            ),
            F.expr("try_cast(unit_concept_id as bigint)").alias(
                "unit_concept_id"
            ),
        )
    )


def _single_aggregations(column, kind):
    # Aggregate the selected single response into its value, text, concept and provenance
    # columns.
    take = (
        (F.col("configured_column") == column)
        & F.coalesce(F.col("is_selected"), F.lit(False))
    )
    return [
        F.max(F.when(take, _response_value(kind))).alias(column),
        F.max(F.when(take, F.col("response_value_text"))).alias(
            f"{column}_text"
        ),
        F.max(F.when(take, F.col("value_concept_id"))).alias(
            f"{column}_concept_id"
        ),
        F.max(F.when(take, _response_provenance())).alias(
            f"{column}_provenance"
        ),
    ]


# ==== Multi-value questions: pick-list booleans or the production JSON array ====

# Ben's ruling 2026-09-09 (decision_register: powerform_multiselect_wide_shape). A multi-value
# question is a pick-list when every selected response it has ever received is coded
# nomenclature (measured 2026-09-09: 41 questions, largest option set 23); it is repeating
# free text otherwise (52 questions, smallest 75 distinct values). Pick-lists publish one
# boolean per option; free text publishes the production JSON array. Both keep the pipe-joined
# _text, and every individual response stays in clinical_form_response.
#
# The option sets are frozen here so the wide shape cannot drift with the data. Each option
# lists every source spelling that means it (an en dash variant of the same option shares the
# boolean). A value that appears later and is in no list still reaches _text and the child,
# and fires the form_picklist_option_coverage acceptance check so it is added deliberately.
# Rendered from 8_dev.s2_evidence.form_picklist_options / form_multi_classification.
